  // Hamburger menu functionality
  const hamburger = document.querySelector('.hamburger');
  const navLinks = document.querySelector('.nav-links');

  hamburger?.addEventListener('click', () => {
      hamburger.classList.toggle('active');
      navLinks.classList.toggle('active');
  });

  // Image loading handler
  document.querySelector('.hero-image').addEventListener('load', function () {
      this.classList.add('loaded');
  });

  document.querySelector('.hero-image').addEventListener('error', function () {
      this.src = 'path-to-fallback-image.jpg';
  });

  // Debounce function for scroll optimization
  function debounce(func, wait = 20, immediate = true) {
      let timeout;
      return function () {
          const context = this, args = arguments;
          const later = function () {
              timeout = null;
              if (!immediate) func.apply(context, args);
          };
          const callNow = immediate && !timeout;
          clearTimeout(timeout);
          timeout = setTimeout(later, wait);
          if (callNow) func.apply(context, args);
      };
  }

  // Update active nav link based on scroll position
  function updateActiveNavLink() {
      const sections = document.querySelectorAll('section');
      const navLinks = document.querySelectorAll('.nav-links a');

      const currentPos = window.scrollY;

      sections.forEach(section => {
          const sectionTop = section.offsetTop - 100;
          const sectionHeight = section.offsetHeight;
          const sectionId = section.getAttribute('id');

          if (currentPos >= sectionTop && currentPos < sectionTop + sectionHeight) {
              navLinks.forEach(link => {
                  link.classList.remove('active');
              });

              const correspondingLink = document.querySelector(`.nav-links a[href="#${sectionId}"]`);
              if (correspondingLink) {
                  correspondingLink.classList.add('active');
              }
          }
      });
  }

  // Smooth scroll for nav links
  document.querySelectorAll('.nav-links a').forEach(link => {
      link.addEventListener('click', (e) => {
          e.preventDefault();
          const targetId = link.getAttribute('href');
          const targetSection = document.querySelector(targetId);

          if (targetSection) {
              targetSection.scrollIntoView({
                  behavior: 'smooth'
              });

              // Close mobile menu if open
              hamburger.classList.remove('active');
              navLinks.classList.remove('active');
          }
      });
  });

  // Intersection Observer for scroll animations
  const observerOptions = {
      root: null,
      rootMargin: '0px',
      threshold: 0.1
  };

  const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
          if (entry.isIntersecting) {
              entry.target.classList.add('visible');
          }
      });
  }, observerOptions);

  // Observe the about wrapper
  const aboutWrapper = document.querySelector('.about-wrapper');
  if (aboutWrapper) {
      observer.observe(aboutWrapper);
  }

  // Parallax effect for skills container
  document.addEventListener('mousemove', (e) => {
      const skillsContainer = document.querySelector('.skills-container');
      if (skillsContainer) {
          const rect = skillsContainer.getBoundingClientRect();
          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;

          const centerX = rect.width / 2;
          const centerY = rect.height / 2;

          const moveX = (x - centerX) / 30;
          const moveY = (y - centerY) / 30;

          skillsContainer.style.transform = `perspective(1000px) rotateY(${moveX}deg) rotateX(${-moveY}deg)`;
      }
  });

  // Reset transform when mouse leaves
  document.querySelector('.skills-container')?.addEventListener('mouseleave', () => {
      document.querySelector('.skills-container').style.transform = 'perspective(1000px) rotateY(0) rotateX(0)';
  });

  // Scroll to top functionality
  const scrollToTopButton = document.getElementById('scrollToTop');

  window.addEventListener('scroll', () => {
      if (window.pageYOffset > 300) {
          scrollToTopButton.classList.add('visible');
      } else {
          scrollToTopButton.classList.remove('visible');
      }
  });

  scrollToTopButton.addEventListener('click', () => {
      window.scrollTo({
          top: 0,
          behavior: 'smooth'
      });
  });

  // Add scroll event listener with debounce
  window.addEventListener('scroll', debounce(updateActiveNavLink));

  // Initialize active nav link on page load
  document.addEventListener('DOMContentLoaded', updateActiveNavLink);


  // Portfolio filter functionality
  const filterButtons = document.querySelectorAll('.filter-btn');
  const portfolioItems = document.querySelectorAll('.portfolio-item');

  filterButtons.forEach(btn => {
      btn.addEventListener('click', () => {
          // Remove active class from all buttons
          filterButtons.forEach(button => button.classList.remove('active'));
          // Add active class to clicked button
          btn.classList.add('active');

          const filterValue = btn.getAttribute('data-filter');

          portfolioItems.forEach(item => {
              if (filterValue === 'all' || item.getAttribute('data-category') === filterValue) {
                  item.style.display = 'block';
              } else {
                  item.style.display = 'none';
              }
          });
      });
  });
